import{_ as t,o as i,c as d,a2 as s}from"./chunks/framework.BM5YPQmL.js";const k=JSON.parse('{"title":"TUI 引擎：全屏桌面及其页面","description":"","frontmatter":{},"headers":[],"relativePath":"zh/arch/tui-engine.md","filePath":"zh/arch/tui-engine.md"}'),a={name:"zh/arch/tui-engine.md"};function o(n,e,c,h,r,l){return i(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="tui-引擎-全屏桌面及其页面" tabindex="-1">TUI 引擎：全屏桌面及其页面 <a class="header-anchor" href="#tui-引擎-全屏桌面及其页面" aria-label="Permalink to &quot;TUI 引擎：全屏桌面及其页面&quot;">​</a></h1><p>TUI 家族是 <code>ocos/services/tui/</code>——25 个源文件，约 1.34 万行，是 仅次于 font 的第二大服务家族。它拥有 L1SVC 类别 20，共 <strong>九个 op， 全部直通路由</strong>（<code>out[0]=0</code>；实时控制台输出即会话，并逐字镜像到 串口分岔）：</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> L1SVC_TUI_TUI</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* tui      (desktop)       */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> L1SVC_TUI_TEST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">       2</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* tui-test (selftests)     */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> L1SVC_TUI_HW</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">         3</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* tui-hw   [page]          */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> L1SVC_TUI_NET</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        4</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* tui-net                  */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> L1SVC_TUI_SYSINFO</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    5</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* tui-sysinfo [page]       */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> L1SVC_TUI_TIME</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">       6</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* tui-time                 */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> L1SVC_TUI_DRV</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        7</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* tui-drv   [page]         */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> L1SVC_TUI_SYS</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        8</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* tui-sys   [page]         */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> L1SVC_TUI_EXT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        9</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* tui-ext                  */</span></span></code></pre></div><p>一个桌面 + 八个页面：op 1 是全屏桌面；其余八个是经典全屏页面及其 自测面（<code>tui-drv</code> 保留其 v2.2.0 的别名角色——与 <code>tui-hw</code> 同体， 独立 op 编号）。</p><h2 id="为什么每个-op-都直通运行-kcap-约束" tabindex="-1">为什么每个 op 都直通运行（kcap 约束） <a class="header-anchor" href="#为什么每个-op-都直通运行-kcap-约束" aria-label="Permalink to &quot;为什么每个 op 都直通运行（kcap 约束）&quot;">​</a></h2><p>L1SVC 文本面通常经 <code>core_kcap_run_fn</code> 捕获命令体的控制台输出—— 捕获激活期间，捕获钩子即控制台钩子，<strong>帧缓冲与串口分岔都看不到 这些字符</strong>（见 <a href="./hidden-mechanisms.html">hidden-mechanisms.md</a>）。这对 TUI 恰恰是错的：全屏会话是逐键实时渲染的，其输出必须在<em>会话运行 期间</em>抵达屏幕。以捕获方式路由 TUI op 会让整个会话期间屏幕一片 空白，然后再把 30 KiB 的 ANSI 杂烩重放进缓冲区。</p><p>裁决记录在源码里：<code>tui-test</code> 最初走捕获路由，但其结论块约 4.4 KiB——4096 字节的服务结果缓冲截断了最终摘要，于是像 v2.2.0 一样 改为直通。同一规则早已约束 <code>sshd</code> 与 <code>power sleep</code>（被捕获的多秒 驻留会吞掉其间打印的每一行控制台输出——OCIRE 监督引导期间实测 发现）。</p><h2 id="文件清单" tabindex="-1">文件清单 <a class="header-anchor" href="#文件清单" aria-label="Permalink to &quot;文件清单&quot;">​</a></h2><p>该家族 <code>src/</code> 目录，按角色：</p><table tabindex="0"><thead><tr><th>组</th><th>文件</th><th>角色</th></tr></thead><tbody><tr><td>dispatch</td><td><code>svc_tui_l1.c</code>、<code>svc_tui_cmd.{c,h}</code></td><td>cat-20 路由（全直通）+ 命令体</td></tr><tr><td>engine</td><td><code>core</code>、<code>win</code>、<code>panel</code>、<code>menu</code>、<code>text</code>、<code>form</code>、<code>input</code></td><td>窗口栈、面板、菜单、文本控件、表单、输入泵</td></tr><tr><td>desktop</td><td><code>desktop</code>、<code>dt_apps</code>、<code>dt_cmdbr</code>、<code>dt_editor</code>、<code>dt_edtrm</code>、<code>dt_files</code>、<code>dt_proc</code></td><td>全屏桌面环境</td></tr><tr><td>classic pages</td><td><code>hw</code>、<code>net</code>、<code>sysinfo</code>、<code>time</code>、<code>sys</code>、<code>drv</code></td><td>分页的信息屏幕</td></tr><tr><td>CJK</td><td><code>chinese</code>、<code>cn_hw</code>、<code>cn_net</code>、<code>cn_sysinfo</code></td><td>同一批页面的中文渲染</td></tr><tr><td>extension</td><td><code>ext</code>、<code>exec</code></td><td>主题/热键注册表与应用执行桥</td></tr><tr><td>tests</td><td><code>test</code></td><td><code>tui-test</code> 测试组</td></tr></tbody></table><p><code>cn_*</code> 文件之所以存在，是因为每个经典页面都有一个中文孪生： <code>tui-hw</code> 与 <code>tui-hw</code> 等价的 CJK 渲染共享数据抓取器，但经 <code>svc_font_render_cn</code> 以双语标签渲染 （见 <a href="./chinese-layer.html">chinese-layer.md</a>）。</p><h2 id="桌面-tui-op-1" tabindex="-1">桌面（<code>tui</code> op 1） <a class="header-anchor" href="#桌面-tui-op-1" aria-label="Permalink to &quot;桌面（\`tui\` op 1）&quot;">​</a></h2><p><code>svc_tui_desktop.c</code> + <code>dt_*</code> 文件：一个全屏桌面环境，含：</p><ul><li><strong>dt_apps</strong>——应用启动器（把 L1 程序注册表渲染为可启动条目），</li><li><strong>dt_cmdbr</strong>——命令栏，</li><li><strong>dt_editor / dt_edtrm</strong>——内建编辑器与终端，</li><li><strong>dt_files</strong>——文件管理器（VFS 后备），</li><li><strong>dt_proc</strong>——进程查看器（<code>SYS_PS</code> 表）。</li></ul><p>渲染经 CJK 感知渲染器（<code>svc_font_render_cn</code>）与窗口/面板/菜单/ 文本/表单/控件层（<code>svc_tui_{win,panel,menu,text,form}.c</code>）；输入 来自控制台输入复用器（PS/2 + 串口 CSI 解码方向键；xterm SGR 鼠标 报告原样透传给鼠标解码器）。IME 即<em>系统</em> IME 引擎 （<code>svc_display_ime_engine.h</code>）——与编辑器所用为同一引擎 （见 <a href="./chinese-layer.html">chinese-layer.md</a>）。</p><h2 id="经典页面" tabindex="-1">经典页面 <a class="header-anchor" href="#经典页面" aria-label="Permalink to &quot;经典页面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><code>tui-hw</code> / <code>tui-drv</code> <code>[page]</code></td><td>硬件/驱动清单，分页——PCIe 缓存、块设备、网卡、声卡、USB 树</td></tr><tr><td><code>tui-net</code></td><td>网络状态——接口、ARP、路由、套接字、防火墙</td></tr><tr><td><code>tui-sysinfo</code> <code>[page]</code></td><td>系统信息——版本、运行时长、内存、任务</td></tr><tr><td><code>tui-time</code></td><td>时钟源——RTC/HPET/PM 定时器/TSC 状态</td></tr><tr><td><code>tui-sys</code> <code>[page]</code></td><td>系统管理——health、klog 尾部、看门狗</td></tr><tr><td><code>tui-ext</code></td><td>TUI 扩展面演示（已注册的热键/主题——见 <a href="./../l1/tui-ext.html">../l1/tui-ext.md</a>）</td></tr><tr><td><code>tui-test</code></td><td>自测组（窗口管理器、控件、输入、渲染检查）</td></tr></tbody></table><h2 id="自测组-tui-test-op-2" tabindex="-1">自测组（<code>tui-test</code> op 2） <a class="header-anchor" href="#自测组-tui-test-op-2" aria-label="Permalink to &quot;自测组（\`tui-test\` op 2）&quot;">​</a></h2><p><code>tui-test</code> 在屏幕上实时运行引擎自己的验收套件：窗口创建/销毁/ z 序、面板与菜单导航、文本控件渲染（含宽单元格 CJK）、表单字段 编辑、输入泵、脏矩形重绘正确性，以及扩展注册表。其结论块约 4.4 KiB——正是决定该家族全直通路由的史实（见上）。E2E 测试组 （<code>tools/tui_g11c_e2e.py</code> 与 tui 验收笔录）通过 grep 这份输出的 串口镜像来无头验证页面。</p><h2 id="输入与输出管道" tabindex="-1">输入与输出管道 <a class="header-anchor" href="#输入与输出管道" aria-label="Permalink to &quot;输入与输出管道&quot;">​</a></h2><ul><li><strong>按键</strong>：控制台输入复用器合并 PS/2 队列与 COM1 串口桥；桥上的 ANSI CSI 解码器把 <code>ESC [ A/B/C/D</code> 方向键与 <code>ESC [ H/F</code> Home/End 预解码为 OC_KEY_* 码，使串口终端与本地键盘同等地驱动 TUI （见 <a href="./interrupts.html">interrupts.md</a>）。</li><li><strong>鼠标</strong>：xterm SGR 报告（<code>ESC [ &lt; ... M/m</code>）经 CSI 解码器原样 透传，交给 TUI 自己的鼠标解码器；本地指针输入来自 USB HID 鼠标 与 i2c-hid 触摸板（见 <a href="./driver-model.html">driver-model.md</a>）。</li><li><strong>输出</strong>：每个页面把 ANSI 转义序列渲染进控制台；串口分岔逐字 镜像它们——这正是验收笔录可 grep、无头自动化得以工作的原因。</li></ul><h2 id="初始化与扩展点" tabindex="-1">初始化与扩展点 <a class="header-anchor" href="#初始化与扩展点" aria-label="Permalink to &quot;初始化与扩展点&quot;">​</a></h2><p>该家族的 <code>OC_SERVICE_DECL_L1</code> 携带带入口点服务中唯一的 init 槽位： <code>tui_ext_init()</code> 在<strong>第一个 op 运行之前</strong>预热内建主题与热键—— 扩展注册表必须在任何页面请求主题之前存在。已注册的扩展（主题、 热键）跨 op 存活整个会话。</p><p>引擎自身的原语（窗口栈、z 序、脏矩形重绘、ANSI 渲染）是 <code>svc_tui_{core,win,panel}.c</code> 的内部实现；面向 L1 应用的公开扩展面 文档见 <a href="./../l1/tui-ext.html">../l1/tui-ext.md</a>，用户指南见 <a href="./../manual/tui-guide.html">../manual/tui-guide.md</a>。</p><h2 id="与其余部分的关系" tabindex="-1">与其余部分的关系 <a class="header-anchor" href="#与其余部分的关系" aria-label="Permalink to &quot;与其余部分的关系&quot;">​</a></h2><ul><li><strong>字体/编码</strong>：每个页面经与控制台相同的 CJK 管道渲染——宽单元 格用 16x16 GB2312 字形，否则 8x16 ASCII （见 <a href="./chinese-layer.html">chinese-layer.md</a>）。</li><li><strong>数据源</strong>：页面是渲染器，渲染的是 CLI 所读的同一批内核表—— <code>net_get_stats()</code>、套接字表、<code>SYS_PS</code>、PMM/堆统计、klog 重放、 看门狗槽位（见 <a href="./network-stack.html">network-stack.md</a>、 <a href="./scheduler.html">scheduler.md</a>、<a href="./../internals/klog.html">../internals/klog.md</a>）。</li><li><strong>串口镜像</strong>：由于各 op 直通，串口分岔承载完整 ANSI 会话—— E2E 测试组（<code>tools/tui_g11c_e2e.py</code>、tui 验收笔录）正是这样无头 验证页面的。</li><li><strong>配置开关已除名</strong>：<code>CONFIG_TUI</code>/<code>CONFIG_CHINESE</code> 随旧 TUI 平面 一并删除——CJK 管道与 TUI 无条件编译。</li></ul>`,26)])])}const u=t(a,[["render",o]]);export{k as __pageData,u as default};
